imageHint: "Fulufjället National Park Njupeskär waterfall",
    descriptionAdvanced: {
      de: "Der Nationalpark Fulufjället liegt in der Provinz Dalarna an der Grenze zu Norwegen und wurde im Jahr 2002 eingeweiht. Mit einer Fläche von etwa 385 Quadratkilometern schützt er ein markantes Sandsteinplateau, das fast völlig frei von Rentierbeweidung ist, was zu einer einzigartigen Flechtenlandschaft geführt hat. Eine der bekanntesten Attraktionen des Parks ist der Njupeskär, mit einer Fallhöhe von 93 Metern der höchste Wasserfall Schwedens. Geologisch gehört das Gebiet zum präkambrischen Sandstein, der eine karge, aber faszinierende Tundra-Vegetation auf dem Hochplateau ermöglicht. Weltweite Bekanntheit erlangte der Park durch den Fund von \"Old Tjikko\", einer Fichte, deren Wurzelsystem seit rund 9.550 Jahren genetisch identisch überdauert hat und damit als einer der ältesten Baumklone der Erde gilt. Der Park ist zudem Lebensraum für den Gerfalken, der an den Felswänden beim Wasserfall brütet, sowie für Braunbären und Elche. Ein modernes Besucherzentrum (Naturum) bietet umfassende Informationen zur Ökologie des Gebiets. Die Infrastruktur umfasst rund 140 Kilometer markierte Wanderwege, die sowohl durch dichte Nadelwälder als auch über die weite, windgepeitschte Hochebene führen.",
      hu: "A Fulufjället Nemzeti Park Dalarna tartományban, a norvég határ mentén fekszik, és 2002-ben nyitották meg a látogatók előtt. A mintegy 385 négyzetkilométeres terület egy hatalmas homokkő fennsíkot foglal magában, amely különlegessége, hogy szinte teljesen mentes a rénszarvas-legeléstől, így a zuzmótakaró itt egyedülálló módon maradhatott fenn. A park legfőbb látványossága a Njupeskär-vízesés, amely 93 méteres magasságával Svédország legmagasabb vízesése. Geológiailag a vidék prekambriumi homokkőből épül fel, amely a fennsíkon kietlen, mégis lenyűgöző tundra-vegetációt tesz lehetővé. Világhírnévre tett szert a park \"Old Tjikko\" felfedezésével; ez egy lucfenyő, amelynek gyökérrendszere körülbelül 9550 éve genetikailag azonos módon maradt fenn, ezzel a világ egyik legidősebb fa-klónjának számít. A terület fontos fészkelőhelye az északi sólyomnak, de barna medvék és jávorszarvasok is gyakran felbukkannak a sűrű erdőkben. A látogatókat egy modern látogatóközpont (Naturum) várja, míg a túrázók mintegy 140 kilométernyi jelzett útvonalon fedezhetik fel a tájat, a völgyektől egészen a szeles fennsíkokig.",
      ro: "Parcul Național Fulufjället este situat în provincia Dalarna, la granița cu Norvegia, și a fost inaugurat în anul 2002. Cu o suprafață de aproximativ 385 de kilometri pătrați, parcul protejează un platou masiv de gresie, care se distinge prin absența aproape totală a pășunatului renilor, fapt ce a permis dezvoltarea unui strat excepțional de licheni. Principala atracție turistică este cascada Njupeskär, care, cu o înălțime de 93 de metri, deține recordul pentru cea mai înaltă cascadă din Suedia. Din punct de vedere geologic, regiunea este formată din gresie precambriană, susținând o vegetație de tundră pe platoul înalt. Parcul a devenit faimos la nivel mondial datorită descoperirii lui \"Old Tjikko\", un molid al cărui sistem radicular a supraviețuit genetic identic timp de aproximativ 9.550 de ani, fiind unul dintre cei mai vechi cloni vegetali de pe planetă. Fauna parcului include șoimul de iarnă, care cuibărește pe stâncile din apropierea cascadei, precum și urși bruni și elani. Facilitățile pentru vizitatori includ un centru Naturum modern și o rețea de 140 de kilometri de trasee marcate care traversează atât păduri de conifere, cât și platouri montane expuse vântului.",
      en: "Fulufjället National Park is situated in Dalarna County along the Norwegian border and was officially opened in 2002. Spanning approximately 385 square kilometers, it protects a distinctive sandstone plateau that is remarkably free from reindeer grazing, resulting in a lush and unique carpet of lichens. The park's most famous landmark is Njupeskär, Sweden's highest waterfall, which features a total vertical drop of 93 meters. Geologically, the area consists of Precambrian sandstone, supporting a stark yet beautiful tundra vegetation on the high plateau. The park gained global fame for being the home of \"Old Tjikko,\" a Norway spruce whose root system has lived for approximately 9,550 years, making it one of the world's oldest known clonal trees. It serves as a vital habitat for the gyrfalcon, which nests on the cliffs near the falls, as well as brown bears and moose. A modern visitor center (Naturum) provides ecological insights, while a network of 140 kilometers of marked trails allows hikers to explore the diverse landscapes from dense forests to windswept heights.",
      es: "Fulufjället alberga Njupeskär, la cascada más alta de Suecia. Aquí también se encuentra Old Tjikko, un abeto cuyo sistema radicular tiene casi 10.000 años de antigüedad.",
      pt: "Fulufjället alberga Njupeskär, a cascata mais alta da Suécia. Aqui também se encontra o Old Tjikko, um abeto cujo sistema radicular tem quase 10.000 anos de idade.",
      fr: "Fulufjället abrite Njupeskär, la plus haute cascade de Suède. On y trouve également Old Tjikko, un épicéa dont le système racinaire est vieux de près de 10 000 ans.",
    },
    factsAdvanced: {
      de: ["Offizielle Eröffnung des Nationalparks im Jahr 2002.", "Fläche von 385 km², höchster Punkt ist Brattfjället (1.042 m).", "Njupeskär ist mit 93 Metern der höchste Wasserfall Schwedens.", "Old Tjikko gilt mit ca. 9.550 Jahren als ältester Baumklon.", "Heimat einer der südlichsten Gerfalken-Populationen Europas.", "Etwa 140 Kilometer markierte Wanderwege stehen zur Verfügung."],
      hu: ["A nemzeti parkot hivatalosan 2002-ben nyitották meg.", "Területe 385 km², legmagasabb pontja a Brattfjället (1042 m).", "A Njupeskär 93 méteres magasságával Svédország legmagasabb vízesése.", "Az \"Old Tjikko\" nevű fa gyökérrendszere kb. 9550 éves.", "Európa egyik legdélebbi északi sólyom állományának otthona.", "A területen nagyjából 140 kilométernyi jelzett turistaút található."],
      ro: ["Inaugurarea oficială a parcului a avut loc în anul 2002.", "Suprafață de 385 km², cel mai înalt punct fiind Brattfjället (1.042 m).", "Njupeskär este cea mai înaltă cascadă din Suedia, având 93 de metri.", "\"Old Tjikko\" este un molid cu o vârstă estimată la 9.550 de ani.", "Găzduiește una dintre cele mai sudice populații de șoim de iarnă.", "Rețeaua de trasee de drumeție însumează circa 140 de kilometri."],
      en: ["The national park was officially inaugurated in 2002.", "Covers 385 km²; its highest point is Brattfjället at 1,042 meters.", "Njupeskär is the highest waterfall in Sweden at 93 meters.", "Home to \"Old Tjikko,\" a clonal tree dated to roughly 9,550 years.", "Protects one of the southernmost gyrfalcon populations in Europe.", "Offers approximately 140 kilometers of marked hiking trails."],
      es: ["Año de fundación 2002", "Njupeskär 93 m", "Old Tjikko 9.550 años", "Superficie 385 km²"],
      pt: ["Ano de fundação 2002", "Njupeskär 93 m", "Old Tjikko 9.550 anos", "Superfície 385 km²"],
      fr: ["Année de fondation 2002", "Njupeskär 93 m", "Old Tjikko 9 550 ans", "Superficie 385 km²"],
    },
