imageHint: "Skuleskogen National Park Slåttdalsskrevan crevice",
    descriptionAdvanced: {
      de: "Der Nationalpark Skuleskogen liegt an der schwedischen Ostseeküste in der Provinz Västernorrland und ist das Herzstück des UNESCO-Weltkulturerbes Hohe Küste (Höga Kusten). Er wurde 1984 gegründet und umfasst eine Fläche von etwa 30 Quadratkilometern. Das Gebiet ist weltweit einzigartig für seine postglaziale Landhebung, die seit dem Rückzug des Eises vor etwa 10.000 Jahren stattfindet und aktuell bei rund 8 Millimetern pro Jahr liegt. Die Topografie ist geprägt von schroffen Granitbergen, die steil aus dem Meer aufragen, und tiefen, urwaldähnlichen Tälern. Das bekannteste Wahrzeichen ist die Slåttdalsskrevan, eine etwa 200 Meter lange und bis zu 40 Meter tiefe Schlucht, die den Slåttdalsberget spaltet. Flora und Fauna sind vielfältig; so findet man hier sowohl die nördlichsten Vorkommen von Haselnusssträuchern als auch seltene Flechten wie die Wolfsflechte. Der Park bietet spektakuläre Aussichten auf den Schärengarten des Bottnischen Meerbusens. Wanderer können den Park auf einem ausgedehnten Wegenetz erkunden, das Teil des bekannten Högakustenleden ist und durch eine Landschaft führt, die sich ständig verändert.",
      hu: "A Skuleskogen Nemzeti Park Svédország keleti partvidékén, Västernorrland tartományban található, és a Magaspart (Höga Kusten) UNESCO Világörökségi terület központi része. Az 1984-ben alapított, mintegy 30 négyzetkilométeres park világszerte egyedülálló a posztglaciális földfelszín-emelkedés szemléltetésében; a jégkorszak vége óta a terület folyamatosan emelkedik, jelenleg évente kb. 8 millimétert. A tájat a tengerből meredeken kiemelkedő gránithegyek és sűrű, őserdőre emlékeztető völgyek jellemzik. Legismertebb természeti képződménye a Slåttdalsskrevan, egy 200 méter hosszú és 40 méter mély szurdok, amely kettéhasítja a Slåttdalsberget tömbjét. A növényvilág különlegessége, hogy itt találhatók a mogyoróbokrok legészakibb természetes előfordulásai, de ritka zuzmófajok is szép számban fordulnak elő. A parkból lenyűgöző kilátás nyílik a Botteni-öböl szigetvilágára. A túrázók számára jól kiépített úthálózat áll rendelkezésre, amely része a híres Högakustenleden útvonalnak, és egy folyamatosan változó, dinamikus tájon vezeti végig a látogatókat.",
      ro: "Parcul Național Skuleskogen este situat pe coasta estică a Suediei, în provincia Västernorrland, reprezentând inima sitului Patrimoniului Mondial UNESCO Coasta Înaltă (Höga Kusten). Înființat în 1984, parcul acoperă o suprafață de aproximativ 30 de kilometri pătrați și este recunoscut global pentru fenomenul de ridicare post-glaciară a scoarței terestre, care continuă și astăzi cu o rată de circa 8 milimetri pe an. Topografia este spectaculoasă, cu munți de granit care se ridică brusc din mare și văi adânci acoperite de păduri seculare. Cea mai faimoasă atracție este Slåttdalsskrevan, un canion lung de 200 de metri și adânc de 40 de metri care despică muntele Slåttdalsberget. Diversitatea biologică este remarcabilă, parcul marcând limita nordică a arealului de răspândire pentru specii precum alunul, dar și habitate pentru licheni rari. Vizitatorii se pot bucura de panorame impresionante asupra arhipelagului din Golful Botnic. Rețeaua de poteci, parte a celebrului traseu Högakustenleden, permite explorarea acestui peisaj dramatic și în continuă schimbare geologică.",
      en: "Skuleskogen National Park is located on the Baltic coast of Sweden in Västernorrland County and serves as the centerpiece of the High Coast (Höga Kusten) UNESCO World Heritage Site. Established in 1984, the park covers about 30 square kilometers and is world-renowned for showcasing post-glacial land uplift, which has been occurring since the ice retreated 10,000 years ago and currently measures about 8 millimeters annually. The topography is defined by rugged granite mountains rising steeply from the sea and deep, primeval forest-like valleys. Its most iconic landmark is the Slåttdalsskrevan, a narrow canyon approximately 200 meters long and 40 meters deep that splits the Slåttdalsberget mountain. The park's biodiversity is unique, featuring the northernmost natural occurrences of hazel trees alongside rare lichens like the wolf lichen. It offers breathtaking views over the Bothnian Sea archipelago. Hikers can traverse the park via an extensive trail system, which is part of the famous High Coast Trail (Högakustenleden), leading through a landscape that is geologically alive and constantly rising.",
      es: "El parque se encuentra en la Costa Alta y muestra impresionantemente el levantamiento de tierras postglacial. Un punto destacado es Slåttdalsskrevan, una grieta rocosa de 200 metros de largo.",
      pt: "O parque está localizado na Costa Alta e mostra impressionantemente o levantamento de terras pós-glacial. Um destaque é o Slåttdalsskrevan, uma fenda rochosa de 200 metros de comprimento.",
      fr: "Le parc est situé sur la Côte Haute et illustre de manière impressionnante le soulèvement des terres après l'ère glaciaire. Un point fort est la Slåttdalsskrevan, une crevasse rocheuse de 200 mètres de long.",
    },
