      en: ["The national park was officially established in 1984.", "Covers approx. 30 km² and is a UNESCO World Heritage site since 2000.", "Current land uplift rate is approximately 8 mm per year.", "Slåttdalsskrevan canyon is 200 m long and 40 m deep.", "Features the northernmost natural growth of hazel trees.", "The highest elevation is Slåttdalsberget at 280 meters."],
