      de: "Ein Tierpark und Forschungszentrum in Bohuslän, das sich der Erhaltung bedrohter Tierarten aus der ganzen Welt widmet.",
      hu: "Állatpark és kutatóközpont Bohuslänben, amely a világ minden tájáról származó veszélyeztetett állatfajok megőrzésével foglalkozik.",
