      de: ["Schwerpunkt bedrohte Arten", "Beherbergt Schneeleoparden", "Eigene Forschungsstation", "Erhaltungszucht-Programme"],
      hu: ["Veszélyeztetett fajokra fókuszál", "Hópárducok is élnek itt", "Saját kutatóállomás", "Fajmegőrző tenyészprogramok"],
