      ro: ["Deschis la data de 27 mai 1965.", "Suprafață de 1,75 kilometri pătrați.", "Primul delfinariu din Suedia (1969).", "Prima telecabină de safari din lume (2011).", "Găzduiește peste 60 de specii de animale.", "Include parcul tematic Bamses Värld."],
      en: ["Opened on May 27, 1965.", "Spans an area of 1.75 square kilometers.", "Sweden's first dolphinarium opened in 1969.", "World's first safari gondola lift (2011).", "Home to over 60 animal species.", "Features the Wildfire wooden roller coaster."],
