imageHint: "Tåkern lake with reeds and bird life",
    descriptionAdvanced: {
      de: "Der Tåkern in der Provinz Östergötland gilt als einer der bedeutendsten Vogelseen Nordeuropas. Mit einer durchschnittlichen Tiefe von nur 0,8 Metern und einer maximalen Tiefe von 2 Metern ist er ein extrem flacher Steppensee, der fast vollständig von einem der größten Schilfgürtel Nordeuropas umschlossen ist. Diese einzigartige Geografie bietet ideale Bedingungen für eine Vielzahl von Wasservögeln, von denen etwa 100 Arten hier nisten. Der Tåkern wurde im 19. Jahrhundert durch eine Absenkung des Wasserspiegels künstlich verkleinert, was die Bildung der weitläufigen Röhrichte begünstigte. Heute ist der gesamte See als Ramsar-Gebiet und Naturschutzgebiet geschützt. Das Naturum Tåkern, ein architektonisch preisgekröntes Besucherzentrum mit einem Dach aus Schilfrohr, bietet interaktive Ausstellungen und Panoramablicke auf das Reservat. Das Gebiet ist besonders bekannt für seine Bestände an Rohrdommeln, Bartmeisen und Rohrweihen sowie für die zehntausenden Graugänse, die sich hier im Herbst sammeln.",
      hu: "A Tåkern-tó Östergötland tartományban található, és Észak-Európa egyik legjelentősebb 'madaras tavaként' ismert. Átlagos mélysége mindössze 0,8 méter, maximuma pedig 2 méter, így egy rendkívül sekély tóról van szó, amelyet Észak-Európa egyik legnagyobb összefüggő nádasa vesz körül. Ez az egyedülálló földrajzi környezet ideális feltételeket biztosít számos vízimadár számára, amelyek közül mintegy 100 faj fészkel itt. A Tåkern területét a 19. században a vízszint mesterséges csökkentésével zsugorították össze, ami elősegítette a kiterjedt nádasok kialakulását. Ma az egész tó Ramsari területként és természetvédelmi rezervátumként élvez védettséget. A Naturum Tåkern látogatóközpont, amely díjnyertes építészeti megoldásairól és nádtetejéről nevezetes, interaktív kiállításokkal és panorámás kilátással várja az érdeklődőket. A terület híres a bölömbika, a barkóscinege és a barna rétihéja állományáról, valamint az ősszel itt gyülekező több tízezer nyári lúdról.",
      ro: "Lacul Tåkern din provincia Östergötland este recunoscut ca unul dintre cele mai importante lacuri pentru păsări din Europa de Nord. Cu o adâncime medie de numai 0,8 metri și o adâncime maximă de 2 metri, este un lac extrem de puțin adânc, înconjurat aproape în totalitate de una dintre cele mai mari centuri de stuf din regiune. Această geografie unică oferă condiții ideale pentru o multitudine de păsări acvatice, aproximativ 100 de specii cuibărind aici. Tåkern a fost micșorat artificial în secolul al XIX-lea prin scăderea nivelului apei, ceea ce a favorizat expansiunea zonelor de stufăriș. Astăzi, întregul lac este protejat ca sit Ramsar și rezervație naturală. Centrul Naturum Tåkern, o clădire premiată arhitectural cu un acoperiș din stuf, oferă expoziții interactive și vederi panoramice asupra rezervației. Zona este renumită pentru populațiile de buhai de baltă, pițigoi de stuf și erete de stuf, precum și pentru zecile de mii de gâște cenușii care se adună aici toamna.",
      en: "Lake Tåkern, located in the province of Östergötland, is widely regarded as one of Northern Europe's premier bird lakes. With an average depth of just 0.8 meters and a maximum of 2 meters, it is an exceptionally shallow lake surrounded by one of the region's largest continuous reed beds. This unique environment provides optimal breeding conditions for roughly 100 different bird species. The lake's current state is largely the result of an artificial water level lowering in the 19th century, which facilitated the expansion of its vast reed ecosystems. Today, the entire lake is a designated Ramsar site and a protected nature reserve. The Naturum Tåkern visitor center, an award-winning architectural structure with a reed-thatched roof, offers interactive exhibits and panoramic vistas of the surrounding landscape. The area is particularly noted for its populations of Eurasian bitterns, bearded reedlings, and marsh harriers, as well as the tens of thousands of greylag geese that gather here during the autumn migration.",
      es: "Tåkern es famoso por sus aguas poco profundas y sus enormes cinturones de cañas. Se considera uno de los lagos de aves con mayor biodiversidad de todo el norte de Europa.",
      pt: "Tåkern é famoso pelas suas águas pouco profundas e pelas suas enormes zonas de caniço. É considerado um dos lagos de aves com maior biodiversidade de todo o norte da Europa.",
      fr: "Tåkern est célèbre pour ses eaux peu profondes et ses immenses roselières. Il est considéré comme l'un des lacs ornithologiques les plus riches en biodiversité de toute l'Europe du Nord.",
    },
    factsAdvanced: {
      de: ["Durchschnittliche Wassertiefe von nur 0,8 Metern.", "Umschlossen von ca. 450 Hektar Schilf.", "Etwa 100 verschiedene Vogelarten brüten hier.", "Das Naturum besitzt ein Dach aus lokalem Schilf.", "In den 1840er Jahren wurde der Seespiegel gesenkt.", "Wichtigster Mauserplatz für Graugänse in Nordeuropa."],
      hu: ["Az átlagos vízmélység mindössze 0,8 méter.", "Körülbelül 450 hektárnyi nádas veszi körül.", "Mintegy 100 madárfaj fészkel itt rendszeresen.", "A Naturum látogatóközpont nádtetővel készült.", "Az 1840-es években csökkentették a vízszintet.", "A nyári ludak legfontosabb vedlőhelye a régióban."],
      ro: ["Adâncimea medie a apei este de doar 0,8 metri.", "Înconjurat de circa 450 de hectare de stuf.", "Aproximativ 100 de specii de păsări cuibăresc aici.", "Naturum are un acoperiș realizat din stuf local.", "Nivelul apei a fost coborât în anii 1840.", "Cel mai important loc de năpârlire pentru gâște cenușii."],
      en: ["Average water depth is only 0.8 meters.", "Surrounded by approximately 450 hectares of reed.", "About 100 different bird species breed here.", "The visitor center features a thatched reed roof.", "The water level was lowered in the 1840s.", "Most important molting site for greylag geese."],
      es: ["Superficie 44 km²", "Profundidad media 0,8 m", "270 especies de aves", "Sitio Ramsar"],
      pt: ["Superfície 44 km²", "Profundidade média 0,8 m", "270 espécies de aves", "Sítio Ramsar"],
      fr: ["Superficie 44 km²", "Profondeur moyenne 0,8 m", "270 espèces d'oiseaux", "Site Ramsar"],
    },
