      ro: ["Fondată în anul 1891 de către Artur Hazelius.", "Parte a celui mai vechi muzeu în aer liber din lume.", "Concentrare pe fauna nativă scandinavă.", "Primește peste 1,3 milioane de vizitatori anual.", "Loc important pentru conservarea raselor domestice vechi.", "Actor central în programele naționale de conservare."],
      en: ["Founded in 1891 by Artur Hazelius.", "Part of the world's oldest open-air museum.", "Focuses primarily on native Scandinavian fauna.", "Attracts over 1.3 million visitors annually.", "Important site for preserving old domestic breeds.", "Central player in national species conservation programs."],
