      de: "Dieser Park schützt eine der größten zusammenhängenden Laubwaldflächen Nordeuropas mit dramatischen Tälern und Schluchten.",
      hu: "Ez a park Észak-Európa egyik legnagyobb összefüggő lombhullató erdőterületét védi, drámai völgyekkel és szurdokokkal.",
