      de: ["Gegründet im Jahr 2001", "Höchster Punkt Schonen (212m)", "Tiefe Schlucht Kopparhatten", "Überwiegend Buchenwälder"],
      hu: ["Alapítva 2001-ben", "Skåne legmagasabb pontja (212m)", "Kopparhatten mély szurdoka", "Főként bükkerdők alkotják"],
