      en: "Björnlandet preserves one of Västerbotten's most valuable old-growth forests, with steep mountains and clear streams.",
      es: "Björnlandet conserva uno de los bosques primarios más valiosos de Västerbotten, con montañas escarpadas y arroyos cristalinos.",
