      ro: ["Fondat în anul 1991", "Pini de pădure virgină", "Urme de incendii vechi", "Habitat pentru râși"],
      en: ["Established in 1991", "Impressive old-growth pines", "Traces of old forest fires", "Home to lynxes"],
      es: ["Fundado en 1991", "Impresionantes pinos de bosque primario", "Huellas de antiguos incendios forestales", "Hogar de linces"],
      pt: ["Fundado em 1991", "Impressionantes pinheiros de floresta primária", "Vestígios de antigos incêndios florestais", "Lar de linces"],
