    imageHint: "Hamra National Park ancient mossy trees",
    descriptionAdvanced: {
      de: "Der Nationalpark Hamra liegt in der Gemeinde Ljusdal in Gävleborgs län und wurde ursprünglich 1909 gegründet, um ein kleines Gebiet unberührten Urwalds zu schützen. Damals war er mit nur 28 Hektar einer der kleinsten Nationalparks Europas, wurde aber 2011 massiv auf über 1.380 Hektar erweitert. Die Erweiterung umfasst nun ein weites Mosaik aus Mooren, Wäldern und Gewässern, was den ökologischen Wert des Parks vervielfacht hat. Hamra ist bekannt für seine über 400 Jahre alten Kiefern und eine enorme Vielfalt an Moosen, Flechten und Pilzen, die auf Totholz spezialisiert sind. Die Tierwelt umfasst Elche, Bären und eine reiche Auswahl an Waldvögeln wie das Auerhuhn. Ein barrierefreier Rundweg ermöglicht es auch Besuchern mit eingeschränkter Mobilität, die faszinierende Urwaldatmosphäre zu erleben. Der Park bietet zudem Einblicke in die traditionelle Nutzung der Moore und die Bedeutung von natürlichen Waldbrandzyklen. Heute ist Hamra ein wichtiges Ziel für Naturfotografen und Wanderer, die die Stille der nordschwedischen Wildnis schätzen.",
      hu: "A Hamra Nemzeti Park Gävleborg megyében, Ljusdal községben található, és eredetileg 1909-ben alapították egy kis területű érintetlen őserdő védelmére. Akkoriban mindössze 28 hektárjával Európa egyik legkisebb nemzeti parkja volt, de 2011-ben hatalmasat bővült, területe ma már meghaladja az 1380 hektárt. A bővítés során lápok, erdők és vizek széles mozaikját vonták védelem alá, ami többszörösére növelte a park ökológiai értékét. Hamra híres a több mint 400 éves fenyőiről, valamint a mohák, zuzmók és gombák óriási választékáról, amelyek a holtfához kötődnek. Az állatvilágban megtalálhatóak a jávorszarvasok, medvék és olyan erdei madarak, mint a siketfajd. Egy akadálymentesített körút lehetővé teszi a mozgáskorlátozott látogatók számára is, hogy megtapasztalják a lenyűgöző őserdei hangulatot. A park betekintést nyújt a lápok hagyományos hasznosításába és a természetes erdőtüzek jelentőségébe is. Ma Hamra a természetfotósok és a túrázók kedvelt célpontja, akik nagyra értékelik az észak-svéd vadon csendjét.",
      ro: "Parcul Național Hamra se află în comuna Ljusdal din comitatul Gävleborg și a fost înființat inițial în 1909 pentru a proteja o mică zonă de pădure virgină. La acea vreme, cu doar 28 de hectare, era unul dintre cele mai mici parcuri naționale din Europa, dar în 2011 a fost extins masiv la peste 1.380 de hectare. Extinderea cuprinde acum un mozaic vast de mlaștini, păduri și cursuri de apă, ceea ce a multiplicat valoarea ecologică a parcului. Hamra este renumit pentru pinii săi vechi de peste 400 de ani și pentru o diversitate enormă de mușchi, licheni și ciuperci specializate pe lemn mort. Fauna include elani, urși și o selecție bogată de păsări de pădure, cum ar fi cocoșul de munte. Un traseu circular accesibilizat permite vizitatorilor cu mobilitate redusă să experimenteze atmosfera fascinantă de pădure virgină. Parcul oferă, de asemenea, informații despre utilizarea tradițională a mlaștinilor și importanța ciclurilor naturale ale incendiilor forestiere. Astăzi, Hamra este o destinație importantă pentru fotografii de natură și drumeții care apreciază liniștea sălbăticiei din nordul Suediei.",
      en: "Hamra National Park is located in the municipality of Ljusdal in Gävleborg County and was originally established in 1909 to protect a small area of untouched primeval forest. At that time, with only 28 hectares, it was one of the smallest national parks in Europe, but it was massively expanded in 2011 to over 1,380 hectares. The expansion now includes a vast mosaic of mires, forests, and waters, which has multiplied the park's ecological value. Hamra is famous for its pines, some over 400 years old, and an enormous variety of mosses, lichens, and fungi specialized in deadwood. Wildlife includes moose, bears, and a rich selection of forest birds such as the capercaillie. An accessible circular trail allows visitors with limited mobility to experience the fascinating primeval forest atmosphere. The park also provides insights into traditional mire use and the significance of natural forest fire cycles. Today, Hamra is a key destination for nature photographers and hikers who appreciate the silence of the North Swedish wilderness.",
      es: "Hamra protege un bosque virgen y una gran zona pantanosa. Originalmente muy pequeño, el parque fue ampliado significativamente en 2011 para incluir más ecosistemas.",
      pt: "Hamra protege uma floresta virgem e uma grande área pantanosa. Originalmente muito pequeno, o parque foi significativamente expandido em 2011 para incluir mais ecossistemas.",
      fr: "Hamra protège une forêt primaire et une vaste zone marécageuse. Initialement très petit, le parc a été considérablement agrandi en 2011 pour inclure davantage d'écosystèmes.",
    },
