      hu: ["1909-ben alapították, az egyik legkorábbi svéd park.", "Területét 2011-ben 28-ról 1380 hektárra növelték.", "Több mint 400 éves erdeifenyők is találhatók itt.", "A holtfához kötődő ökoszisztémák védelmére szakosodott.", "Akadálymentes túraútvonalakat is kínál a látogatóknak.", "A ritka siketfajd fontos fészkelőhelye."],
      ro: ["Fondat în 1909 ca unul dintre primele parcuri naționale.", "Suprafața a fost extinsă în 2011 de la 28 la 1.380 hectare.", "Găzduiește exemplare de pin cu vârste de peste 400 de ani.", "Specializat în protejarea ecosistemelor dependente de lemn mort.", "Oferă trasee de drumeție accesibilizate pentru toți vizitatorii.", "Loc important de cuibărit pentru cocoșul de munte."],
      en: ["Established in 1909 as one of Sweden's first parks.", "Area expanded from 28 to 1,380 hectares in 2011.", "Home to pine stands that are over 400 years old.", "Specializes in protecting deadwood-dependent ecosystems.", "Offers accessible hiking trails for all types of visitors.", "Important breeding site for the rare capercaillie bird."],
